class KVStore:
    def __init__(self):
        # key -> (value, expires_at or None)
        self._data: dict[str, tuple[str, int | None]] = {}

    def _live(self, key: str, now: int) -> tuple[str, int | None] | None:
        entry = self._data.get(key)
        if entry is None:
            return None
        if entry[1] is not None and now >= entry[1]:
            del self._data[key]
            return None
        return entry

    def set(self, key: str, value: str, ttl: int | None = None, now: int = 0) -> None:
        self._data[key] = (value, None if ttl is None else now + ttl)

    def get(self, key: str, now: int = 0) -> str | None:
        entry = self._live(key, now)
        return entry[0] if entry else None

    def delete(self, key: str, now: int = 0) -> bool:
        if self._live(key, now) is None:
            return False
        del self._data[key]
        return True

    def keys(self, prefix: str = "", now: int = 0) -> list[str]:
        return sorted(k for k in list(self._data) if k.startswith(prefix) and self._live(k, now))

