class KVStore:
    def __init__(self):
        # key -> (value, expires_at or None)
        self._base: dict[str, tuple[str, int | None]] = {}
        # Open transactions, innermost last: key -> entry or _DELETED
        self._layers: list[dict[str, object]] = []

    @staticmethod
    def _expired(entry, now: int) -> bool:
        return entry[1] is not None and now >= entry[1]

    def _lookup(self, key: str):
        for layer in reversed(self._layers):
            if key in layer:
                entry = layer[key]
                return None if entry is _DELETED else entry
        return self._base.get(key)

    def _write(self, key: str, entry) -> None:
        if self._layers:
            self._layers[-1][key] = entry
        elif entry is _DELETED:
            self._base.pop(key, None)
        else:
            self._base[key] = entry

    def set(self, key: str, value: str, ttl: int | None = None, now: int = 0) -> None:
        self._write(key, (value, None if ttl is None else now + ttl))

    def get(self, key: str, now: int = 0) -> str | None:
        entry = self._lookup(key)
        if entry is None or self._expired(entry, now):
            return None
        return entry[0]

    def delete(self, key: str, now: int = 0) -> bool:
        if self.get(key, now) is None:
            return False
        self._write(key, _DELETED)
        return True

    def keys(self, prefix: str = "", now: int = 0) -> list[str]:
        candidates = set(self._base)
        for layer in self._layers:
            candidates.update(layer)
        return sorted(k for k in candidates if k.startswith(prefix) and self.get(k, now) is not None)

    def begin(self) -> None:
        self._layers.append({})

    def _pop(self) -> dict[str, object]:
        if not self._layers:
            raise RuntimeError("no transaction in progress")
        return self._layers.pop()

    def rollback(self) -> None:
        self._pop()

    def commit(self) -> None:
        for key, entry in self._pop().items():
            self._write(key, entry)
